# 第 7 批：卦 54-63（归妹、丰、旅、巽、兑、涣、节、中孚、小过、既济）

HEXAGRAMS = {
  "54": {"zh": "归妹卦下兑上震，出嫁而未得正位。它讲名分未正——归妹不是正配，位不当则事难成。", "en": "Guimei is joy below, movement above — a bride going out without her proper place. It's about a name not set right: this isn't a proper match, and with the place wrong the thing is hard to complete.", "ja": "帰妹は下が兑、上が震。嫁ぐが正しい位を得ない。名分が正しくないことを表す——帰妹は正配ではなく、位が当たらないと事は成りにくい。"},
  "55": {"zh": "丰卦下离上震，光明盛大。它讲丰盛之时——日头正午就偏西，丰盛时要存持盈之戒。", "en": "Feng is clarity below, movement above — great brightness. It's about a time of abundance: the sun at noon starts to decline — in fullness, keep a guard against overflow.", "ja": "豊は下が離、上が震。明かりが盛ん。豊かな時を表す——日は真昼に傾き始める。豊かさにあって満ちることを戒める。"},
  "56": {"zh": "旅卦下艮上离，行旅在外。它讲旅居之理——在外的人，柔顺为贵，放低姿态自处。", "en": "Lu is mountain below, clarity above — traveling away from home. It's about the way of the traveler: away from home, softness is precious, keep yourself lowly.", "ja": "旅は下が艮、上が離。旅に出ている。旅居の道理を表す——旅の人は柔順を尊び、低く自らを処する。"},
  "57": {"zh": "巽卦为风，风行无形。它讲柔入之理——巽用来申明命令、推行政事，柔而能入，入而能断。", "en": "Xun is wind, blowing without form. It's about gentle penetration — Xun declares commands and carries out affairs: soft yet penetrating, penetrating yet decisive.", "ja": "巽は風、形なく吹く。柔らかく入る道理を表す——巽は命令を述べて事を行い、柔で入り、入って断てる。"},
  "58": {"zh": "兑卦为泽，泽润万物。它讲和悦——和悦可亲，用喜悦引导众人，就能使人忘了劳苦。", "en": "Dui is the marsh, moistening all things. It's about joy and harmony — harmony makes you approachable; leading people with joy makes them forget their toil.", "ja": "兑は沢、万物を潤す。和やかな喜びを表す——和悦は親しみやすく、喜びで人を導けば、その労を忘れさせる。"},
  "59": {"zh": "涣卦下坎上巽，涣散。它讲散而能聚——涣其私群，用大牲祭祀，涣散之时正是王者聚人之机。", "en": "Huan is danger below, compliance above — scattering. It's about dispersing that gathers: scatter your private clique, offer a great sacrifice — scattering is when a ruler gathers people.", "ja": "渙は下が坎、上が巽。散ること。散って聚められることを表す——私的な群れを散らし、大いな犠牲を供える。渙る時こそ王が人を集める機だ。"},
  "60": {"zh": "节卦下兑上坎，节制。它讲节度——用制度来节，不伤财、不害民；但苦节不可久守。", "en": "Jie is joy below, danger above — limitation. It's about measure: limit by rule, without wasting wealth or harming people. But bitter austerity can't be sustained.", "ja": "節は下が兑、上が坎。節度。節の道理を表す——制度で節し、財を傷つけ民を害しない。しかし苦しい節は長く守れない。"},
  "61": {"zh": "中孚卦下兑上巽，中心诚信。它讲诚信——孚就是信，心中充实，诚能感通豚鱼。", "en": "Zhongfu is joy below, compliance above — inner faith. It's about sincerity: Fu means trust; the heart is full, and faith reaches even to pigs and fish.", "ja": "中孚は下が兑、上が巽。心の誠信。誠を表す——孚とは信であり、心が充実すれば、誠は豚や魚にも通じる。"},
  "62": {"zh": "小过卦下艮上震，稍有越过。它讲小事宜慎——可做小事不可做大事，飞鸟留下声音，卑下胜过高上。", "en": "Xiaoguo is mountain below, movement above — slight excess. It's about care in small matters: small things yes, great things no; the flying bird leaves its cry — staying low beats soaring high.", "ja": "小過は下が艮、上が震。少し越える。小事には慎むべきことを表す——小事はできても大事はできない。飛ぶ鳥が声を残す。低いほうが高いより勝る。"},
  "63": {"zh": "既济卦水在火上，事已成功。它讲成功须戒——开头成、结尾乱，既济之时，患在不思变。", "en": "Jiji is water over fire — the task complete. It's about caution in success: formed at the start, disordered at the end. In Jiji, the danger is not thinking of change.", "ja": "既済は火の上に水。事が成った。成功には戒めが要ることを表す——初めは成っても終わりは乱れる。既済の時、患いは変わることを思わぬことにある。"},
}

LINES = {
  # 54 归妹
  "54-0": {"zh": "你在最底下，是归妹的开始，以媵妾的卑微身份而行其本分。处下而能尽分，虽不足也可行——安于其位，其行就正。", "en": "You're at the bottom, the start of Guimei — in the lowly place of a handmaid, yet fulfilling your part. Low yet fulfilling your role, though lacking you can act. At ease in your place, your conduct is right.", "ja": "一番下にいて、帰妹の初め。媵の賤しい身で本分を行う。下にいて分を尽くせば、足りなくても行える。その位に安んじれば、その行いは正しい。"},
  "54-1": {"zh": "你在下卦正中，刚中而上应六五，眼光不及远。所见虽偏却能守正——幽静自守，是本分所安。", "en": "You're at the center of the lower trigram, strong and centered, matched above with the fifth line, your sight not reaching far. Though your view is narrow you keep rightness. Quiet self-keeping is where your part rests.", "ja": "下卦の中央にいて、剛中で六五に応じるが、見る目は遠く及ばない。見るところは偏っても正を守れる。幽かに自らを守るのが、分の安む所だ。"},
  "54-2": {"zh": "你在下卦最上面，不中不正，想求为正室反而归为媵妾。不安其分而求进，反失其所——柔而不正，故不能自达。", "en": "You're at the top of the lower trigram — off-center and improper — seeking to be the true wife yet ending as a concubine. Restless in your place and seeking advancement, you lose your ground. Soft and improper, you can't arrive.", "ja": "下卦の最上部にいて、中も正も外れ、正室になろうとしてかえって媵となった。分に安んじず進もうとして、所を失う。柔で正しくないので、自ら達せない。"},
  "54-3": {"zh": "你在上卦下面，刚而居柔，无正应而等待其时。有德而无遇，就待时——不妄求，所以虽迟却有期。", "en": "You're below the upper trigram, strong in a soft place, no proper match, waiting for your time. Virtue without encounter means waiting. No rash seeking, so though late there's a date.", "ja": "上卦の下にいて、剛で柔の位にあり、正しい応えがなく時を待つ。徳があって巡り合いがなければ、時を待つのみ。妄りに求めないので、遅くても期がある。"},
  "54-4": {"zh": "你在尊位，柔中而下应九二，其德盛而能自下。以尊下贤，不尚装饰而尚德——德之盛如月将圆。", "en": "You're in the place of honor, soft and centered, reaching down to the second line — virtue full yet humble. In high station you humble yourself before the worthy, valuing virtue not ornament. Its fullness like a moon nearing full.", "ja": "尊い位にいて、柔らかく中を得て九二に応じる。徳は盛んなのに自ら下る。尊くて賢者を下し、飾りではなく徳を尊ぶ。その徳の盛りは月が満ちんとするようだ。"},
  "54-5": {"zh": "你到了卦的顶，是归妹的终点，有其礼而无其实。礼存实亡，就成不了事——有名无实，故无可取。", "en": "You're at the top of the hexagram, Guimei at its end — the rite without the reality. Form remains, substance gone, so nothing can be completed. Name without reality has nothing to recommend it.", "ja": "卦の頂点にいて、帰妹の終わり。礼はあるが実がない。礼は残って実が亡ければ、事は成せない。名だけで実がないので、取るべくものがない。"},
  # 55 丰
  "55-0": {"zh": "你在最底下，是丰的开始，与九四同德相遇。处丰之初，得同类相资——虽对等也无妨，前往可以有为。", "en": "You're at the bottom, the start of Feng — meeting the fourth line of like virtue. At the start of abundance, finding a peer to help you. Though equals, no harm; going forward you can act.", "ja": "一番下にいて、豊の初め。九四と徳を同じくして巡り合う。豊の初めに同じ類の助けを得る。対等でも差し支えなく、往いて何か成せる。"},
  "55-1": {"zh": "你在下卦正中，柔正而被六五遮蔽，光明不显。明被遮，往则见疑——积其诚以发之，蔽就开了。", "en": "You're at the center of the lower trigram, soft and proper, hidden by the fifth line — your light unseen. Hidden, going brings suspicion. Gather sincerity to bring it out and the cover opens.", "ja": "下卦の中央にいて、柔らかく正しいが六五に覆われて明かりは見えない。明が覆われれば往けば疑われる。誠を積んで発すれば、その覆いは開ける。"},
  "55-2": {"zh": "你在下卦最上面，刚正却被上六遮蔽，作用不行。明大蔽，不可有为——能自止其用，故可无过。", "en": "You're at the top of the lower trigram, rigid and upright but hidden by the top line — your use won't go. Greatly obscured, you can't act. Stopping your own use avoids fault.", "ja": "下卦の最上部にいて、剛正だが上六に覆われて働きが行かない。明が大きく覆われれば、何も成せない。自らその用を止めれば、過ちは免れる。"},
  "55-3": {"zh": "你在上卦下面，与初九同德相遇，虽蔽而可行。所蔽虽同，得同德者相助，其行可有成。", "en": "You're below the upper trigram, meeting the first line of like virtue — though hidden, you can act. Hidden the same way, but with a like-minded ally your action can succeed.", "ja": "上卦の下にいて、初九と徳を同じくして巡り合う。覆われていても行ける。覆われ方は同じでも、同じ徳の者と助け合えば、その行いは成せる。"},
  "55-4": {"zh": "你在尊位，柔和中正而能招致天下之明。以柔中致贤明，庆誉自来——虚己而受人之明，是丰之主。", "en": "You're in the place of honor, soft and centered, able to gather the world's brightness. With soft centrality you attract the worthy and their light — praise comes on its own. Emptying yourself to receive others' light: Feng's master.", "ja": "尊い位にいて、柔らかく中を得て天下の明かりを招く。柔中で賢明を致せば、慶誉は自ら来る。己を虚しくして人の明を受ける——これが豊の主だ。"},
  "55-5": {"zh": "你到了卦的顶，是丰的终点，自高而蔽，人都离去。丰极则自蔽而人离——高而不与人接，其终必孤。", "en": "You're at the top of the hexagram, Feng at its end — self-exalted and obscured, everyone leaves. At abundance's peak you hide yourself and people depart. High without contact, you end alone.", "ja": "卦の頂点にいて、豊の終わり。みずから高ぶって覆われ、人は皆去る。豊が極まれば自らを蔽い人は離れる。高くて人と交わらぬなら、終わりは必ず孤りだ。"},
  # 56 旅
  "56-0": {"zh": "你在最底下，是旅的开始，处下而琐细，志趣卑下。处旅而志趣卑琐，灾自取——柔而不正，不能自振。", "en": "You're at the bottom, the start of Lu — low and petty, your aims mean. Traveling with a petty spirit brings trouble on yourself. Soft and improper, you can't rouse yourself.", "ja": "一番下にいて、旅の初め。下にあって些細で、志が卑しい。旅にあって志が卑小なら、災いは自ら招く。柔で正しくないので、自ら立てない。"},
  "56-1": {"zh": "你在下卦正中，柔正而得所安，有资财、有仆从。处旅而得其次，内有资、外有助——柔中故能自安。", "en": "You're at the center of the lower trigram, soft and proper, finding your resting place, with means and a servant. Traveling and finding your inn, means within and help without. Soft-centered, you can settle.", "ja": "下卦の中央にいて、柔らかく正しく安きを得る。財があり従者もいる。旅して次を得、内に資産、外に助け。柔中なので自ら安んじられる。"},
  "56-2": {"zh": "你在下卦最上面，过刚而不中，失其所安与所依。刚而过则人不与，故失所安——虽正仍不免于危。", "en": "You're at the top of the lower trigram — overly rigid, off-center — losing your rest and support. Too rigid and people won't stay with you, so you lose your place. Though right, you can't avoid danger.", "ja": "下卦の最上部にいて、剛が過ぎて中を外れ、安きと頼る者を失う。剛が過ぎれば人と与しないので、安きを失う。正しくても危いのは免れない。"},
  "56-3": {"zh": "你在上卦下面，刚而居柔，得其资具而未得其位。有具而无位，故心不快——旅之道贵在得所安。", "en": "You're below the upper trigram, strong in a soft place, with means but not your proper station. Having the means without the place, your heart is unsettled. The traveler's way values finding rest.", "ja": "上卦の下にいて、剛で柔の位にあり、その具は得たが位を得ていない。具があって位がなければ心は快くない。旅の道は安きを得ることを尊ぶ。"},
  "56-4": {"zh": "你在尊位，柔中而处旅，有所花费而终有所得。有文明之德，虽小有所失，终以誉命——柔中故能通上。", "en": "You're in the place of honor, soft and centered, traveling — you spend a little but gain in the end. With cultivated virtue, though you lose a little you end praised. Soft-centered, you reach those above.", "ja": "尊い位にいて、柔らかく中を得て旅に処する。費すところがあっても終わりに得る所がある。文明の徳があれば、少し失っても終には誉められる。柔中なので上に通じる。"},
  "56-5": {"zh": "你到了卦的顶，是旅的终点，先得后失，巢已焚。处旅之极而骄，故先笑后号——失其柔顺，是自取。", "en": "You're at the top of the hexagram, Lu at its end — first gain then loss, your nest burned. At travel's extreme you grow proud, so laughter turns to wailing. Losing softness is self-inflicted.", "ja": "卦の頂点にいて、旅の終わり。先に得て後失い、巣は焼けた。旅の極で驕るので、先は笑い後は叫び。柔順を失ったのは自ら招いたことだ。"},
  # 57 巽
  "57-0": {"zh": "你在最底下，是巽的开始，柔而多疑，进退不定。疑而不能决，就用刚来决——柔济之以刚，是正。", "en": "You're at the bottom, the start of Xun — soft and doubtful, wavering. Doubt without decision: use firmness to decide. Softness aided by firmness is right.", "ja": "一番下にいて、巽の初め。柔で疑いが多く、進退が定まらない。疑って決められぬなら、剛で決する。柔を剛で補うのが正しい。"},
  "57-1": {"zh": "你在下卦正中，刚中而过于巽，其诚可通。巽到床下，是太过——然中实而诚，故能通神明。", "en": "You're at the center of the lower trigram, strong and centered yet overly yielding — your faith connects. Yielding under the bed is excess, but centered and genuine, it reaches the divine.", "ja": "下卦の中央にいて、剛中で巽りすぎる。その誠は通じる。床の下まで巽るのは過ぎだが、中が実して誠があるので、神明に通じる。"},
  "57-2": {"zh": "你在下卦最上面，过刚而不中，屡巽而人不与。巽不出于诚，频频作态，人就轻你——勉强者事必穷。", "en": "You're at the top of the lower trigram — overly rigid, off-center — repeatedly yielding but no one follows. Yielding not from faith, done again and again, makes people slight you. Forced effort comes to nothing.", "ja": "下卦の最上部にいて、剛が過ぎて中を外れ、たびたび巽っても人は従わない。誠から出ない巽りを繰り返せば、人は軽く見る。無理をする者は事が穷まる。"},
  "57-3": {"zh": "你在上卦下面，柔正而巽于上下之刚。以柔正处刚之间，能顺而不失——有所获，是巽之效。", "en": "You're below the upper trigram, soft and proper, yielding to the rigidity above and below. Soft and proper among the strong, you comply without losing yourself. Gaining something is Xun's effect.", "ja": "上卦の下にいて、柔らかく正しく上下の剛に巽う。柔正で剛の間にあって、従って失わない。得る所がある——これが巽りの効だ。"},
  "57-4": {"zh": "你身居尊位，刚中而正，是巽的主爻，其令有节。刚中而巽，令不暴——申明命令而后行，故有终。", "en": "You're in the place of honor, strong, centered and right — Xun's main line — your commands measured. Strong-centered and yielding, your commands aren't harsh. Declare then act, so you reach an end.", "ja": "尊い位にいて、剛中で正しく、巽の主爻。その命令には節度がある。剛中で巽えば命令は暴しくない。命を申してから行うので、終わりがある。"},
  "57-5": {"zh": "你到了卦的顶，是巽的终点，过巽而失其所守。巽极则失其刚——失刚就失了自断之力，其道穷。", "en": "You're at the top of the hexagram, Xun at its end — over-yielding, losing your grip. At Xun's extreme you lose firmness. Losing firmness loses your power to decide — your way ends.", "ja": "卦の頂点にいて、巽の終わり。巽りすぎて守るものを失う。巽が極まれば剛を失う。剛を失えば自ら断ずる力を失い、その道は穷まる。"},
  # 58 兑
  "58-0": {"zh": "你在最底下，是兑的开始，以刚居正，其悦和而不流。悦之初，无所系应，故悦也和——和而不偏，是正。", "en": "You're at the bottom, the start of Dui — strong in a right place, your joy harmonious not dissolute. At the start of joy, no attachments, so the joy is harmonious. Harmonious not biased: that's right.", "ja": "一番下にいて、兑の初め。剛で正しく居り、その悦びは和して流れない。悦びの初めは繋がる応えがなく、悦びは和やか。和して偏らぬのが正だ。"},
  "58-1": {"zh": "你在下卦正中，刚中而悦，其悦本于诚。悦而以诚，人不疑其佞——刚中自守，故悔可消。", "en": "You're at the center of the lower trigram, strong and centered with joy — joy rooted in faith. Joy with sincerity, no one suspects flattery. Strong-centered and self-keeping, regret can vanish.", "ja": "下卦の中央にいて、剛中で悦ぶ。その悦びは誠に基づく。悦んで誠があれば、人は佞りを疑わない。剛中を守るので悔いは消える。"},
  "58-2": {"zh": "你在下卦最上面，不中不正，来求人之悦己。求人之悦己而无所守，是邪道——柔而不正，故至于此。", "en": "You're at the top of the lower trigram — off-center and improper — seeking others to please you. Seeking approval without principles is a crooked way. Soft and improper, you came to this.", "ja": "下卦の最上部にいて、中も正も外れ、人来て悦ばせようとする。人に悦ばれることを求めて守るものがないのは邪道だ。柔で正しくないので、ここに至った。"},
  "58-3": {"zh": "你在上卦下面，刚而居柔，介然守正而未自定。介于邪正之间而能自守，虽未安而有喜——能疾其邪，是其介。", "en": "You're below the upper trigram, strong in a soft place — upright but not yet settled. Between wrong and right yet keeping yourself — unsettled but with joy. Loathing the wrong is your integrity.", "ja": "上卦の下にいて、剛で柔の位にあり、くっきりと正を守るがまだ定まらない。邪正の間で自ら守れれば、安まなくても喜びがある。邪を憎むのがその節操だ。"},
  "58-4": {"zh": "你在尊位，刚中而近上六之阴，被它所悦而信之。信所不当信，害将至——位尊而悦，不可不戒。", "en": "You're in the place of honor, strong and centered, near the yin of the top line — charmed and trusting it. Trusting what shouldn't be trusted, harm is coming. High and pleased, you must be watchful.", "ja": "尊い位にいて、剛中で上六の陰に近く、それに悦んで信じる。信ずべからざるを信じれば、害は来る。尊くて悦ぶゆえ、戒めないわけにはいかない。"},
  "58-5": {"zh": "你到了卦的顶，是兑的终点，引同类以相悦。引人以悦，其心不可知——悦之极而不出于正，是兑之末。", "en": "You're at the top of the hexagram, Dui at its end — drawing your kind to enjoy together. Drawing people to pleasure, the heart can't be known. Joy at its peak not from rightness is Dui's dregs.", "ja": "卦の頂点にいて、兑の終わり。同じ類を引いて悦び合う。人を悦びに誘えば、その心は計り知れない。悦びの極が正から出ないのは、兑の末だ。"},
  # 59 涣
  "59-0": {"zh": "你在最底下，是涣的开始，得壮马以救其难。涣之始，救之贵速——得刚者相助，就可以济。", "en": "You're at the bottom, the start of Huan — a strong horse to rescue your difficulty. At the start of scattering, rescue values speed. With a strong helper, you can get through.", "ja": "一番下にいて、渙の初め。強い馬を得て難を救う。渙の初めは救うのに速さが肝心。剛なる者の助けを得れば、渡れる。"},
  "59-1": {"zh": "你在下卦正中，刚中而涣，奔就其机以为安。涣之时，得所依则安——刚中能自择，故悔可消。", "en": "You're at the center of the lower trigram, strong and centered, scattering — hurrying to the right place for safety. In scattering, finding support brings ease. Strong-centered and choosing well, regret vanishes.", "ja": "下卦の中央にいて、剛中で渙る。機を奔って安きを求める。渙る時は頼る所を得れば安い。剛中で自ら選べるので、悔いは消える。"},
  "59-2": {"zh": "你在下卦最上面，不中不正而能涣其私身。能散其私以从公，虽不中也可无悔——忘其身者可以济涣。", "en": "You're at the top of the lower trigram — off-center and improper — yet scattering your private self. Dispelling the private to follow the public, though off-center you can be faultless. Forgetting yourself can overcome scattering.", "ja": "下卦の最上部にいて、中も正も外れているが私身を散らせる。私を散らして公に従えば、中を外れても悔いはない。身を忘れる者は渙りを救える。"},
  "59-3": {"zh": "你在上卦下面，柔正而涣其私党，以成一统。能散其私党者，其功最大——使众人合而为一，非寻常所及。", "en": "You're below the upper trigram, soft and proper, scattering your private clique to make one union. Scattering private factions is the greatest achievement — uniting many into one is beyond the ordinary.", "ja": "上卦の下にいて、柔らかく正しく私党を散らして一つに統べる。私党を散らせる者の功は最も大きい。衆を一つに合わせるのは、並みの及ぶ所ではない。"},
  "59-4": {"zh": "你在尊位，刚中而涣其号令，以及其居。涣之大者在于号令——出其令而无所私，人心可合。", "en": "You're in the place of honor, strong and centered, scattering your commands to your dwelling. The great scattering lies in commands. Issue them without selfishness and hearts can unite.", "ja": "尊い位にいて、剛中で号令を渙らせ、その居に及ぼす。渙りの大なるは号令にある。令を出して私がなければ、人心は合わせられる。"},
  "59-5": {"zh": "你到了卦的顶，是涣的终点，去其伤害而远出之。涣之极可以去其害——远其所当远，故可无过。", "en": "You're at the top of the hexagram, Huan at its end — removing harm and sending it far away. At scattering's peak you can remove the harm. Keep far what should be far, so you avoid fault.", "ja": "卦の頂点にいて、渙の終わり。害を除いて遠くへ出す。渙りの極は害を除ける。遠ざけるべきを遠ざければ、過ちはない。"},
  # 60 节
  "60-0": {"zh": "你在最底下，是节的开始，时未可行，故不出。节在于知时——时未可则不出，是本分当然。", "en": "You're at the bottom, the start of Jie — the time isn't right, so you don't go out. Limitation lies in knowing the time. When it isn't time, staying in is your proper part.", "ja": "一番下にいて、節の初め。まだ行く時でないので出ない。節は時を知ることにある。時が許さぬなら出ないのが、分の当然だ。"},
  "60-1": {"zh": "你在下卦正中，刚中而当可行之时，却仍不出。时可出而不出，是失其节——节之过，与不节同失。", "en": "You're at the center of the lower trigram, strong and centered — the time allows going out, yet you don't. When you should go but don't, you miss the measure. Over-limitation errs like no limitation.", "ja": "下卦の中央にいて、剛中で行ける時なのに出ない。出るべき時に出ないのは、節を失うこと。節の過ぎは、節しないのと同じく誤る。"},
  "60-2": {"zh": "你在下卦最上面，不中不正，不能自节而后嗟叹。不能节于前、嗟于后，悔已晚——能知所嗟，则可无过。", "en": "You're at the top of the lower trigram — off-center and improper — unable to restrain yourself, then lamenting. Can't limit before, lament after — regret is late. Knowing what you lament, you can avoid fault.", "ja": "下卦の最上部にいて、中も正も外れ、自ら節せず後になって嘆く。前は節できず後で嘆くのは、悔いも遅い。嘆くところを知れば、過ちは免れる。"},
  "60-3": {"zh": "你在上卦下面，柔正而上承九五，安于其节。节而能安，则不苦——柔顺得正，故其节可行。", "en": "You're below the upper trigram, soft and proper, receiving the fifth line above — at ease with your limit. Limit with ease isn't bitter. Soft and proper, your limit can be carried out.", "ja": "上卦の下にいて、柔らかく正しく九五を承け、その節に安んずる。節して安んじられれば苦しくない。柔顺で正を得たので、その節は行える。"},
  "60-4": {"zh": "你身居尊位，刚中而节，人乐从之。节而使人不以为苦，是甘节——中正以节，故往有功。", "en": "You're in the place of honor, strong and centered in your limit, and people gladly follow. A limit people don't find bitter is a sweet limit. Centered and upright, going achieves.", "ja": "尊い位にいて、剛中で節し、人は喜んで従う。節して人を苦しめないのは甘い節だ。中正で節するので、往けば功がある。"},
  "60-5": {"zh": "你到了卦的顶，是节的终点，节之太过而人不能堪。节而至于苦，则不可久——虽正而穷，然其志可取。", "en": "You're at the top of the hexagram, Jie at its end — limiting too much, beyond what people can bear. A limit turned bitter can't last. Though right, it ends; yet the intention is worthy.", "ja": "卦の頂点にいて、節の終わり。節が過ぎて人が耐えられない。節が苦しくなれば長く続かない。正しくても穷まるが、その志は取り得る。"},
  # 61 中孚
  "61-0": {"zh": "你在最底下，是中孚的开始，其诚未有所向。诚之道贵专一——有所他向，心就不安，故不可不戒。", "en": "You're at the bottom, the start of Zhongfu — your faith not yet directed. Faith values singleness. Directed elsewhere, the heart is uneasy, so you must be watchful.", "ja": "一番下にいて、中孚の初め。誠はまだ向かう所がない。誠の道は専一が肝心。他へ向けば心は安まないので、戒めないわけにはいかない。"},
  "61-1": {"zh": "你在下卦正中，刚中而诚，其诚感人而不远。诚积于中，虽在幽远人亦应——不求人知而人自和。", "en": "You're at the center of the lower trigram, strong and centered with faith — it moves people far away. Faith heaped within, even in the remote people respond. Not seeking to be known, people harmonize on their own.", "ja": "下卦の中央にいて、剛中で誠がある。その誠は遠くの人にも及ぶ。誠が内に積もれば、幽かな所でも人が応じる。人に知られようと求めず、人は自ずと和す。"},
  "61-2": {"zh": "你在下卦最上面，不中不正，其心无主。中心无主，则喜怒哀乐皆系于人——不信诸己，故不能自定。", "en": "You're at the top of the lower trigram — off-center and improper — your heart without a master. Without a master within, joy and anger all depend on others. Not trusting yourself, you can't settle.", "ja": "下卦の最上部にいて、中も正も外れ、心に主がない。心に主がなければ、喜怒哀楽はみな人にかかわる。自らを信じないので、定まれない。"},
  "61-3": {"zh": "你在上卦下面，柔正而上从九五，绝其私党。舍其私与上从于君，是绝其类——绝私则无害。", "en": "You're below the upper trigram, soft and proper, following the fifth line above, cutting off your private clique. Leaving private ties to follow the ruler is severing your kind. No private ties, no harm.", "ja": "上卦の下にいて、柔らかく正しく九五に従い、私党を絶つ。私的な与を捨てて君に従うのは、その類を絶つことだ。私を絶てば害はない。"},
  "61-4": {"zh": "你身居尊位，刚中而诚，固结天下而不私。有诚以固结天下，人皆归之——中实之孚，为孚之主。", "en": "You're in the place of honor, strong and centered with faith — binding the world without selfishness. With faith you hold the world together and all come to you. Centered, real faith: the master of Fu.", "ja": "尊い位にいて、剛中で誠があり、天下を固く結んで私しない。誠で天下を結べば、人は皆帰する。中が実した孚は、孚の主だ。"},
  "61-5": {"zh": "你到了卦的顶，是孚的终点，声闻过高而无其实。有声无实，是孚之穷——过而不知止，其道必困。", "en": "You're at the top of the hexagram, Fu at its end — renowned too high without substance. Sound without reality is Fu's exhaustion. Excess without knowing to stop, your way is sure to be trapped.", "ja": "卦の頂点にいて、孚の終わり。名声が高すぎて実がない。声があって実がないのは、孚の穷まりだ。過ぎて止まらぬなら、その道は必ず困る。"},
  # 62 小过
  "62-0": {"zh": "你在最底下，是小过的开始，以柔而好上，进得太骤。小过之世，可在下不可在上——初就想高飞，故进也骤。", "en": "You're at the bottom, the start of Xiaoguo — soft yet fond of rising, advancing too fast. In an age of small excess, the low is right, not the high. Wanting to soar from the start makes your rush.", "ja": "一番下にいて、小過の初め。柔で上を好み、進みが急すぎる。小過の世では下にあるのがよく上ではない。初めから高く飛ぼうとするので進みが急だ。"},
  "62-1": {"zh": "你在下卦正中，柔正而过其祖、不及其君。过而能自下，不犯其上——过其所当过，不及所不当及。", "en": "You're at the center of the lower trigram, soft and proper — passing your ancestor but not reaching your ruler. Exceeding yet staying low, not offending above. Exceed what should be exceeded, not what shouldn't.", "ja": "下卦の中央にいて、柔らかく正しく、その祖を過ぎて君には及ばない。過ぎても自ら下り、上を犯さない。過ぎるべきを過ぎ、及ぶべきでないところに及ばない。"},
  "62-2": {"zh": "你在下卦最上面，过刚而不中，不能自防其过。刚过而不知自防，则被人所乘——自防者所以保身。", "en": "You're at the top of the lower trigram — overly rigid, off-center — unable to guard your own excess. Too rigid without self-guard, others take advantage. Self-guarding is how you keep safe.", "ja": "下卦の最上部にいて、剛が過ぎて中を外れ、自分の過ぎを防げない。剛が過ぎて自ら防ぐことを知らなければ、人につけ込まれる。自ら防ぐのは身を保つゆえだ。"},
  "62-3": {"zh": "你在上卦下面，刚而居柔，过而不极，可以相遇。刚而能柔，故不过——往则危，不可不戒，因时处之。", "en": "You're below the upper trigram, strong in a soft place — excess short of extreme, so you can meet. Strong yet soft, you don't overdo. Going is dangerous, so be watchful and act by the time.", "ja": "上卦の下にいて、剛で柔の位にあり、過ぎて極まらないので巡り合える。剛で柔を作えれば過ぎない。往けば危ういので戒めを要し、時によって処する。"},
  "62-4": {"zh": "你在尊位，柔中而不能大有为，其泽未下。有位无才，故不能成大——所能者小事，是本分。", "en": "You're in the place of honor, soft and centered but unable to do greatly — your grace hasn't reached below. Position without ability can't achieve the great. Small things are your part.", "ja": "尊い位にいて、柔らかく中を得るが大いには為せず、恵みは下に及ばない。位はあって才がなければ大を成せない。できるのは小事、それが本分だ。"},
  "62-5": {"zh": "你到了卦的顶，是过的终点，过而不知止，无所遇。过之极则无所遇，是穷——高而不知反，灾自己。", "en": "You're at the top of the hexagram, excess at its end — passing on without stop, meeting nothing. At excess's extreme you meet nothing — exhaustion. High without returning, disaster comes of itself.", "ja": "卦の頂点にいて、過ぎの終わり。過ぎて止まらず、遇う者がない。過ぎの極は遇う所なし、それが穷まりだ。高くて返ることを知らねば、災いは自ら来る。"},
  # 63 既济
  "63-0": {"zh": "你在最底下，是既济的开始，曳住车轮不进。既成之后，患在轻进——能止其进，可保其成。", "en": "You're at the bottom, the start of Jiji — holding back the wheel, not advancing. After completion, the danger is rushing ahead. Stopping your advance preserves your achievement.", "ja": "一番下にいて、既済の初め。車輪を引いて進まない。成った後は、軽く進むことが患い。進みを止められれば、その成りを保てる。"},
  "63-1": {"zh": "你在下卦正中，柔正而失其可行之具。中正自守，所失者不求自得——不逐者，其道自复。", "en": "You're at the center of the lower trigram, soft and proper, having lost the means to act. Keep center and rightness and what's lost returns unasked. Don't chase — your way restores itself.", "ja": "下卦の中央にいて、柔らかく正しく、行く具を失う。中正を守れば、失ったものは求めずに得られる。追わぬ者は、その道が自ずと戻る。"},
  "63-2": {"zh": "你在下卦最上面，刚正而以刚伐远，久而后克。既济之时而事于外，其难可知——用小人则益乱。", "en": "You're at the top of the lower trigram, rigid and upright, attacking afar with force — long, then victory. In Jiji, taking on outside endeavors is clearly hard. Using small men only increases disorder.", "ja": "下卦の最上部にいて、剛正で剛をもって遠くを討ち、久しくして勝つ。既済の時に外で事を起こすのは難しいと知れる。小人を用いれば、乱れは増すばかりだ。"},
  "63-3": {"zh": "你在上卦下面，柔正而处既济，其备常具。既成而能常备，可以不败——于无事之时戒，是其明。", "en": "You're below the upper trigram, soft and proper in Jiji — always prepared. Complete yet always ready, you avoid defeat. Warning yourself in quiet times: that's clarity.", "ja": "上卦の下にいて、柔らかく正しく既済に処し、備えを常に整える。成っていて常に備えられれば敗れずに済む。事のない時に戒めるのが、その明るさだ。"},
  "63-4": {"zh": "你身居尊位，刚中而正，其祭以诚不以物。既济之盛，不在礼隆而在诚至——诚则实受其福。", "en": "You're in the place of honor, strong, centered and right — your sacrifice by faith, not by gifts. Jiji's abundance isn't in rich rites but in utmost faith. Faith receives real blessing.", "ja": "尊い位にいて、剛中で正しく、祭りは物ではなく誠による。既済の盛りは礼の隆かさではなく誠の至りにある。誠ならば実にその福を受ける。"},
  "63-5": {"zh": "你到了卦的顶，是既济的终点，其首既濡，其危已至。既济之极而将反，其危在首——不知其变，故至于溺。", "en": "You're at the top of the hexagram, Jiji at its end — your head is wet, danger arrived. At Jiji's peak, about to reverse, the danger is at the head. Not knowing change, you end up drowning.", "ja": "卦の頂点にいて、既済の終わり。頭はすでに濡れ、危いは来た。既済の極は返ろうとしており、危いは頭にある。その変わりを知らないので、沈むに至る。"},
}
